// Saved calculations (spec §9.2, §9.3). Never throws to callers.
import { toCanonical } from '../domain/format'
import { emi } from '../domain/loan'
import { Decimal, round2 } from '../domain/money'
import type { CalculatedLoan, CanonicalInput, Currency } from '../domain/types'
import { validateInputs } from '../domain/validate'
import { readItem, removeItem, storageAvailable, writeItem } from './safeStorage'

export const HISTORY_KEY = 'emi-calc.v1.history'
export const HISTORY_LIMIT = 20

export interface HistoryEntry {
  id: string
  createdAt: string
  currency: Currency
  input: CanonicalInput
  monthlyPayment: string
}

export type HistoryResult = { ok: true; entries: HistoryEntry[] } | { ok: false }

const isObject = (v: unknown): v is Record<string, unknown> =>
  typeof v === 'object' && v !== null && !Array.isArray(v)

/** Spec §9.2: an element is kept only if every check passes; otherwise it is dropped. */
function validEntry(value: unknown): HistoryEntry | null {
  // 1. Type guard.
  if (!isObject(value) || !isObject(value.input)) return null
  const { id, createdAt, currency, monthlyPayment } = value
  const { amount, rate, tenure, unit } = value.input
  if (typeof id !== 'string' || id === '') return null
  if (typeof createdAt !== 'string') return null
  const time = Date.parse(createdAt)
  if (Number.isNaN(time)) return null
  // Check the year as it will be displayed (local time), so the shown date always has a
  // four-digit year from 2000 to 9999 (G4.5 review G45-2).
  const year = new Date(time).getFullYear()
  if (year < 2000 || year > 9999) return null
  if (currency !== 'PKR' && currency !== 'USD') return null
  if (typeof amount !== 'string' || typeof rate !== 'string') return null
  if (typeof tenure !== 'number' || !Number.isInteger(tenure)) return null
  if (unit !== 'years' && unit !== 'months') return null
  if (typeof monthlyPayment !== 'string') return null

  // 2. The input is valid under today's rules.
  const result = validateInputs({ amount, rate, tenure: String(tenure), unit })
  if (!result.ok) return null

  // 3. The stored input is exactly the canonical form.
  const canonical = toCanonical(result.value)
  if (
    canonical.amount !== amount ||
    canonical.rate !== rate ||
    canonical.tenure !== tenure ||
    canonical.unit !== unit
  ) {
    return null
  }

  // 4. The stored payment equals the recomputed one (emi only, so loading stays cheap).
  let stored: Decimal
  try {
    stored = new Decimal(monthlyPayment)
  } catch {
    return null
  }
  const { amount: principal, annualRate, months } = result.value
  if (!stored.eq(round2(emi(principal, annualRate.div(1200), months)))) return null

  return { id, createdAt, currency, input: canonical, monthlyPayment }
}

/** Not valid JSON or not a list → empty. Invalid elements dropped, duplicate ids dropped, at most 20. */
export function parseHistory(raw: string | null): HistoryEntry[] {
  if (raw === null) return []
  let value: unknown
  try {
    value = JSON.parse(raw)
  } catch {
    return []
  }
  if (!Array.isArray(value)) return []
  const seen = new Set<string>()
  const entries: HistoryEntry[] = []
  for (const element of value) {
    // The first 20 valid, unique entries are the whole result, so stop there: a tampered
    // store with thousands of elements stays fast (G4.5 review G45-3).
    if (entries.length === HISTORY_LIMIT) break
    const entry = validEntry(element)
    if (!entry || seen.has(entry.id)) continue
    seen.add(entry.id)
    entries.push(entry)
  }
  return entries
}

/** Reads the stored list now. Every write starts from this, never from in-memory state (D-13). */
function readCurrent(): HistoryResult {
  const stored = readItem(HISTORY_KEY)
  return stored.ok ? { ok: true, entries: parseHistory(stored.value) } : { ok: false }
}

export function loadHistory(): { available: boolean; entries: HistoryEntry[] } {
  if (!storageAvailable()) return { available: false, entries: [] }
  const current = readCurrent()
  return current.ok
    ? { available: true, entries: current.entries }
    : { available: false, entries: [] }
}

let idCounter = 0
function newId(): string {
  try {
    if (typeof crypto.randomUUID === 'function') return crypto.randomUUID()
  } catch {
    // Fall through to the timestamp-plus-counter fallback (spec §9.2).
  }
  idCounter += 1
  return `${Date.now()}-${idCounter}`
}

export function createEntry(
  loan: CalculatedLoan,
  currency: Currency,
  now = new Date(),
): HistoryEntry {
  return {
    id: newId(),
    createdAt: now.toISOString(),
    currency,
    input: toCanonical(loan.input),
    monthlyPayment: loan.monthlyPayment.toFixed(2),
  }
}

const sameCalculation = (a: HistoryEntry, b: HistoryEntry) =>
  a.currency === b.currency &&
  a.input.amount === b.input.amount &&
  a.input.rate === b.input.rate &&
  a.input.tenure === b.input.tenure &&
  a.input.unit === b.input.unit

/** Spec §9.3: re-read, skip a repeat of the newest entry as just read, insert at the top, keep 20. */
export function saveEntry(entry: HistoryEntry): HistoryResult {
  const current = readCurrent()
  if (!current.ok) return current
  const [newest] = current.entries
  if (newest && sameCalculation(newest, entry)) return current
  const entries = [entry, ...current.entries].slice(0, HISTORY_LIMIT)
  return writeItem(HISTORY_KEY, JSON.stringify(entries)).ok ? { ok: true, entries } : { ok: false }
}

/** Deletes by id from the list as just read (D-13). */
export function deleteEntry(id: string): HistoryResult {
  const current = readCurrent()
  if (!current.ok) return current
  const entries = current.entries.filter((e) => e.id !== id)
  const written =
    entries.length === 0 ? removeItem(HISTORY_KEY) : writeItem(HISTORY_KEY, JSON.stringify(entries))
  return written.ok ? { ok: true, entries } : { ok: false }
}

/** Clear all removes the key entirely (AC-12.4). */
export function clearHistory(): HistoryResult {
  return removeItem(HISTORY_KEY).ok ? { ok: true, entries: [] } : { ok: false }
}
// Browser storage that never throws to callers (spec §9.1).
// Every access is wrapped, including reading `window.localStorage` itself, which throws in
// Safari when storage is blocked.

export type StorageResult<T> = { ok: true; value: T } | { ok: false }

const PROBE_KEY = 'emi-calc.v1.probe'
let available: boolean | undefined

/** Checks once per visit that storage can be written and removed. */
export function storageAvailable(): boolean {
  if (available === undefined) {
    try {
      const store = window.localStorage
      store.setItem(PROBE_KEY, PROBE_KEY)
      store.removeItem(PROBE_KEY)
      available = true
    } catch {
      available = false
    }
  }
  return available
}

export function readItem(key: string): StorageResult<string | null> {
  try {
    return { ok: true, value: window.localStorage.getItem(key) }
  } catch {
    return { ok: false }
  }
}

export function writeItem(key: string, value: string): StorageResult<void> {
  try {
    window.localStorage.setItem(key, value)
    return { ok: true, value: undefined }
  } catch {
    return { ok: false }
  }
}

export function removeItem(key: string): StorageResult<void> {
  try {
    window.localStorage.removeItem(key)
    return { ok: true, value: undefined }
  } catch {
    return { ok: false }
  }
}
// Currency and theme preferences (spec §9.2).
import type { Currency } from '../domain/types'
import { readItem, writeItem } from './safeStorage'

export type Theme = 'system' | 'light' | 'dark'

export interface Settings {
  currency: Currency
  theme: Theme
}

export const SETTINGS_KEY = 'emi-calc.v1.settings'
export const defaultSettings: Settings = { currency: 'PKR', theme: 'system' }

const CURRENCIES: readonly string[] = ['PKR', 'USD']
const THEMES: readonly string[] = ['system', 'light', 'dark']

/**
 * Not valid JSON, or not a plain object → both defaults. Each field that is missing or not an
 * allowed value falls back to its own default; the other field is kept. Never throws.
 * The inline script in index.html applies the same rule to the theme before first paint.
 */
export function parseSettings(raw: string | null): Settings {
  if (raw === null) return defaultSettings
  let value: unknown
  try {
    value = JSON.parse(raw)
  } catch {
    return defaultSettings
  }
  if (typeof value !== 'object' || value === null || Array.isArray(value)) return defaultSettings
  const { currency, theme } = value as Record<string, unknown>
  return {
    currency:
      typeof currency === 'string' && CURRENCIES.includes(currency)
        ? (currency as Currency)
        : defaultSettings.currency,
    theme:
      typeof theme === 'string' && THEMES.includes(theme)
        ? (theme as Theme)
        : defaultSettings.theme,
  }
}

export function loadSettings(): Settings {
  const stored = readItem(SETTINGS_KEY)
  return stored.ok ? parseSettings(stored.value) : defaultSettings
}

/** Best effort: if storage is blocked, settings simply live in memory for this visit (AC-6.6). */
export function saveSettings(settings: Settings): void {
  writeItem(SETTINGS_KEY, JSON.stringify(settings))
}

import {
  createContext,
  useContext,
  useEffect,
  useReducer,
  type Dispatch,
  type ReactNode,
} from 'react'
import { loadHistory } from '../storage/history'
import { loadSettings, saveSettings, type Settings, type Theme } from '../storage/settings'
import { appReducer, initialState, type Action, type AppState } from './appReducer'

interface AppContextValue {
  state: AppState
  dispatch: Dispatch<Action>
  /** Changes a setting and persists it (spec §3.2: "Update settings and persist"). */
  updateSettings: (change: Partial<Settings>) => void
}

const AppContext = createContext<AppContextValue | null>(null)

const DARK_QUERY = '(prefers-color-scheme: dark)'

function resolveTheme(theme: Theme): 'light' | 'dark' {
  if (theme !== 'system') return theme
  return window.matchMedia(DARK_QUERY).matches ? 'dark' : 'light'
}

/** Applies the resolved theme to <html> and follows the device while "System" is chosen. */
function useAppliedTheme(theme: Theme) {
  useEffect(() => {
    const apply = () => {
      document.documentElement.dataset.theme = resolveTheme(theme)
    }
    apply()
    if (theme !== 'system') return
    const media = window.matchMedia(DARK_QUERY)
    media.addEventListener('change', apply)
    return () => media.removeEventListener('change', apply)
  }, [theme])
}

// Settings and history are read before the first render, so nothing flashes the defaults.
const init = (): AppState => ({
  ...initialState,
  settings: loadSettings(),
  history: { ...loadHistory(), removeFailed: false },
})

export function AppProvider({ children }: { children: ReactNode }) {
  const [state, dispatch] = useReducer(appReducer, undefined, init)
  useAppliedTheme(state.settings.theme)

  function updateSettings(change: Partial<Settings>) {
    if (change.currency) dispatch({ type: 'setCurrency', currency: change.currency })
    if (change.theme) dispatch({ type: 'setTheme', theme: change.theme })
    // Merge over what is stored now, not this tab's copy, so another tab's change to the
    // other setting is not overwritten (G4.4 review G44-1; same idea as D-13).
    saveSettings({ ...loadSettings(), ...change })
  }

  return (
    <AppContext.Provider value={{ state, dispatch, updateSettings }}>
      {children}
    </AppContext.Provider>
  )
}

export function useApp(): AppContextValue {
  const value = useContext(AppContext)
  if (!value) throw new Error('useApp must be used inside <AppProvider>')
  return value
}
import { useRef, type FormEvent, type RefObject } from 'react'
import { calculateLoan } from '../../domain/loan'
import type { ErrorCode, Field, Unit } from '../../domain/types'
import { validateInputs } from '../../domain/validate'
import { createEntry, saveEntry } from '../../storage/history'
import { useApp } from '../AppContext'
import { copy } from '../copy'
import { CurrencySelect } from './CurrencySelect'

const FIELD_ORDER: Field[] = ['amount', 'rate', 'tenure']
const UNITS: Unit[] = ['years', 'months']

interface TextFieldProps {
  id: Field
  label: string
  value: string
  error: ErrorCode | undefined
  inputMode: 'decimal' | 'numeric'
  inputRef: RefObject<HTMLInputElement | null>
  onChange: (value: string) => void
}

function TextField({ id, label, value, error, inputMode, inputRef, onChange }: TextFieldProps) {
  const errorId = `${id}-error`
  return (
    <div className="field">
      <label htmlFor={id}>{label}</label>
      <input
        ref={inputRef}
        id={id}
        type="text"
        inputMode={inputMode}
        autoComplete="off"
        value={value}
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? errorId : undefined}
        onChange={(e) => onChange(e.target.value)}
      />
      {/* Spec §8.3: errors sit under their field, in a polite live region. */}
      <p id={errorId} className="field-error" aria-live="polite">
        {error ? copy.err[error] : ''}
      </p>
    </div>
  )
}

export function LoanForm() {
  const { state, dispatch } = useApp()
  const { inputs, errors, settings } = state
  const amountRef = useRef<HTMLInputElement>(null)
  const rateRef = useRef<HTMLInputElement>(null)
  const tenureRef = useRef<HTMLInputElement>(null)

  function onSubmit(event: FormEvent) {
    event.preventDefault()
    const result = validateInputs(inputs)
    if (!result.ok) {
      dispatch({ type: 'invalid', errors: result.errors })
      // Spec §8.3: focus the first invalid field in order amount → rate → tenure.
      const refs = { amount: amountRef, rate: rateRef, tenure: tenureRef }
      const first = FIELD_ORDER.find((f) => result.errors[f])
      if (first) refs[first].current?.focus()
      return
    }
    const loan = calculateLoan(result.value)
    dispatch({ type: 'calculated', loan })
    // Spec §9.3: save only after a successful calculation. A failed save makes saved
    // calculations unavailable for the rest of the visit.
    if (state.history.available) {
      const saved = saveEntry(createEntry(loan, settings.currency))
      dispatch(
        saved.ok
          ? { type: 'historyChanged', entries: saved.entries }
          : { type: 'historyUnavailable' },
      )
    }
  }

  function onReset() {
    dispatch({ type: 'reset' })
    amountRef.current?.focus()
  }

  const edit = (field: 'amount' | 'rate' | 'tenure') => (value: string) =>
    dispatch({ type: 'edit', field, value })

  return (
    <form className="card form-card" noValidate onSubmit={onSubmit}>
      <CurrencySelect />
      <TextField
        id="amount"
        label={copy.field.amount(settings.currency)}
        value={inputs.amount}
        error={errors.amount}
        inputMode="decimal"
        inputRef={amountRef}
        onChange={edit('amount')}
      />
      <TextField
        id="rate"
        label={copy.field.rate}
        value={inputs.rate}
        error={errors.rate}
        inputMode="decimal"
        inputRef={rateRef}
        onChange={edit('rate')}
      />
      <div className="tenure-row">
        <TextField
          id="tenure"
          label={copy.field.tenure}
          value={inputs.tenure}
          error={errors.tenure}
          inputMode="numeric"
          inputRef={tenureRef}
          onChange={edit('tenure')}
        />
        <div className="field">
          <label htmlFor="unit">{copy.field.unit}</label>
          <select
            id="unit"
            value={inputs.unit}
            onChange={(e) => dispatch({ type: 'setUnit', unit: e.target.value as Unit })}
          >
            {UNITS.map((u) => (
              <option key={u} value={u}>
                {copy.field.unitOptions[u]}
              </option>
            ))}
          </select>
        </div>
      </div>
      <div className="actions">
        <button type="submit" className="primary">
          {copy.btn.calculate}
        </button>
        <button type="button" className="secondary" onClick={onReset}>
          {copy.btn.reset}
        </button>
      </div>
    </form>
  )
}
import { useEffect, useRef, useState } from 'react'
import { calculateLoan } from '../../domain/loan'
import { validateInputs } from '../../domain/validate'
import {
  clearHistory,
  deleteEntry,
  HISTORY_KEY,
  parseHistory,
  type HistoryEntry as Entry,
} from '../../storage/history'
import { useApp } from '../AppContext'
import { copy } from '../copy'
import { ConfirmDialog } from './ConfirmDialog'
import { HistoryEntry } from './HistoryEntry'

/** Where focus goes after the next render (spec §8.3, AC-12.1, D-30). */
type FocusTarget = 'heading' | 'clearAll' | { restore: string }

export function HistoryPanel() {
  const { state, dispatch, updateSettings } = useApp()
  const { available, entries, removeFailed } = state.history
  const [confirming, setConfirming] = useState(false)
  const headingRef = useRef<HTMLHeadingElement>(null)
  const clearAllRef = useRef<HTMLButtonElement>(null)
  const listRef = useRef<HTMLUListElement>(null)
  const pendingFocus = useRef<FocusTarget | null>(null)

  // Apply a pending focus move once the DOM reflects the new state. Child effects (the dialog
  // closing) run first, so focus never lands behind a still-open modal.
  useEffect(() => {
    const target = pendingFocus.current
    if (!target) return
    pendingFocus.current = null
    // A target that can't take focus any more (Clear all disabled, or the entry removed by
    // another tab meanwhile) falls back to the heading, so focus is never dropped (G45-1).
    let element: HTMLElement | null | undefined = headingRef.current
    if (target === 'clearAll' && clearAllRef.current && !clearAllRef.current.disabled) {
      element = clearAllRef.current
    } else if (typeof target === 'object') {
      const selector = `[data-entry-id="${CSS.escape(target.restore)}"] [data-action="restore"]`
      element = listRef.current?.querySelector<HTMLButtonElement>(selector) ?? headingRef.current
    }
    element?.focus()
  })

  // Spec §9.3: another tab changed the history (or cleared all storage): reload the list.
  useEffect(() => {
    if (!available) return
    const onStorage = (event: StorageEvent) => {
      if (event.key !== HISTORY_KEY && event.key !== null) return
      const next = parseHistory(event.key === null ? null : event.newValue)
      const focused = document.activeElement?.closest('[data-entry-id]')
      const focusedId = focused?.getAttribute('data-entry-id')
      if (focusedId && !next.some((e) => e.id === focusedId)) pendingFocus.current = 'heading'
      dispatch({ type: 'historyReloaded', entries: next })
    }
    window.addEventListener('storage', onStorage)
    return () => window.removeEventListener('storage', onStorage)
  }, [available, dispatch])

  function onRestore(entry: Entry, button: HTMLButtonElement) {
    const inputs = {
      amount: entry.input.amount,
      rate: entry.input.rate,
      tenure: String(entry.input.tenure),
      unit: entry.input.unit,
    }
    const result = validateInputs(inputs)
    if (!result.ok) return // unreachable: entries are fully validated on load (§9.2)
    dispatch({
      type: 'restore',
      inputs,
      currency: entry.currency,
      loan: calculateLoan(result.value),
    })
    updateSettings({ currency: entry.currency })
    // §8.3: focus stays on Restore. Set it explicitly: WebKit does not focus buttons on click.
    button.focus()
  }

  function onDelete(id: string) {
    const index = entries.findIndex((e) => e.id === id)
    const result = deleteEntry(id)
    if (!result.ok) {
      dispatch({ type: 'historyRemoveFailed' })
      return
    }
    // AC-12.1: the next entry's Restore, else the previous one's, else the heading.
    const remaining = new Set(result.entries.map((e) => e.id))
    const next = entries.slice(index + 1).find((e) => remaining.has(e.id))
    const previous = entries
      .slice(0, Math.max(index, 0))
      .reverse()
      .find((e) => remaining.has(e.id))
    const target = next ?? previous
    pendingFocus.current = target ? { restore: target.id } : 'heading'
    dispatch({ type: 'historyChanged', entries: result.entries })
  }

  function onCancelClear() {
    setConfirming(false)
    pendingFocus.current = 'clearAll'
  }

  function onConfirmClear() {
    const result = clearHistory()
    setConfirming(false)
    if (result.ok) {
      pendingFocus.current = 'heading'
      dispatch({ type: 'historyChanged', entries: [] })
    } else {
      pendingFocus.current = 'clearAll'
      dispatch({ type: 'historyRemoveFailed' })
    }
  }

  return (
    <section className="card history-card">
      <h2 id="history-title" ref={headingRef} tabIndex={-1}>
        {copy.history.title}
      </h2>
      {!available ? (
        <p className="status">{copy.history.unavailable}</p>
      ) : entries.length === 0 ? (
        <p className="status">{copy.history.empty}</p>
      ) : (
        <ul ref={listRef} className="history-list" aria-labelledby="history-title">
          {entries.map((entry) => (
            <HistoryEntry key={entry.id} entry={entry} onRestore={onRestore} onDelete={onDelete} />
          ))}
        </ul>
      )}
      <div aria-live="polite">
        {removeFailed && <p className="field-error">{copy.history.removeFailed}</p>}
      </div>
      <button
        type="button"
        ref={clearAllRef}
        className="secondary"
        disabled={!available || entries.length === 0}
        onClick={() => setConfirming(true)}
      >
        {copy.history.clearAll}
      </button>
      <ConfirmDialog open={confirming} onCancel={onCancelClear} onConfirm={onConfirmClear} />
    </section>
  )
}
import { useEffect, useRef } from 'react'
import { copy } from '../copy'

interface ConfirmDialogProps {
  open: boolean
  onCancel: () => void
  onConfirm: () => void
}

// Spec §8.3 (D-20, D-30): native modal <dialog>, no JS focus trap. Focus is set in code:
// Cancel when it opens; the parent moves focus after it closes.
export function ConfirmDialog({ open, onCancel, onConfirm }: ConfirmDialogProps) {
  const dialogRef = useRef<HTMLDialogElement>(null)
  const cancelRef = useRef<HTMLButtonElement>(null)

  useEffect(() => {
    const dialog = dialogRef.current
    if (!dialog) return
    if (open && !dialog.open) {
      dialog.showModal()
      cancelRef.current?.focus()
    } else if (!open && dialog.open) {
      dialog.close()
    }
  }, [open])

  return (
    <dialog
      ref={dialogRef}
      className="confirm-dialog"
      aria-labelledby="clear-dialog-text"
      aria-describedby="clear-dialog-hint"
      onCancel={(event) => {
        // Escape: close through state, so focus handling stays in one place.
        event.preventDefault()
        onCancel()
      }}
    >
      <p id="clear-dialog-text" className="dialog-text">
        {copy.dialog.clearText}
      </p>
      <p id="clear-dialog-hint" className="hint">
        {copy.dialog.clearHint}
      </p>
      <div className="actions">
        <button type="button" ref={cancelRef} className="secondary" onClick={onCancel}>
          {copy.dialog.cancel}
        </button>
        <button type="button" className="primary" onClick={onConfirm}>
          {copy.dialog.confirm}
        </button>
      </div>
    </dialog>
  )
}
